async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${r.status}`);return r.json()}
async function start(){
  try{const s=await json('/api/hub/status');const version=document.querySelector('#version');const status=document.querySelector('#hub-status');if(version)version.textContent=s.version||'dev';if(status)status.textContent='Hub 正常運作'}catch(e){const status=document.querySelector('#hub-status');if(status)status.textContent='Hub 狀態異常'}
  try{const b=await json('/api/bootstrap/status');if(b.required){const card=document.querySelector('#bootstrap-card')||document.querySelector('#system-bootstrap');const command=document.querySelector('#bootstrap-command');if(card)card.classList.remove('hidden');if(command)command.textContent=b.install_command||'等待支援的 Raspberry Pi 版本'}}catch(e){}
  if(document.querySelector('#update-check'))initUpdates()
  if(document.body.dataset.page==='home')loadHomeDashboard()
  if(document.body.dataset.module==='power')loadPowerDashboard()
  if(document.body.dataset.module==='system')loadSystemDashboard()
  if(document.body.dataset.module==='dosing')loadDosingDashboard()
  if(document.body.dataset.module==='calculator')loadCalculatorDashboard()
  if(document.body.dataset.module==='thread')loadThreadDashboard()
  if(document.body.dataset.module==='water')loadWaterDashboard()
}
async function loadWaterDashboard(){const content=document.querySelector('#module-content'),placeholder=document.querySelector('#module-placeholder');try{const d=await json('/api/hub/water');content.textContent='';const s=d.status;if(!s.configured)throw new Error('Google Sheets 尚未設定');if(s.stale){const warn=document.createElement('div');warn.className='mapping-note stale-warning';warn.textContent=`Google 同步失敗，顯示最後資料：${s.last_error||'未知錯誤'}`;content.append(warn)}const labels={no3:'NO₃',po4:'PO₄',ph:'pH',sg:'比重 SG',kh:'KH',ca:'Ca',mg:'Mg'},units={no3:'ppm',po4:'ppm',ph:'',sg:'',kh:'dKH',ca:'ppm',mg:'ppm'};const grid=document.createElement('div');grid.className='water-grid';for(const[k,label]of Object.entries(labels)){const pts=d.history[k]||[],last=s.values[k],card=document.createElement('section');card.className='metric water-metric';card.innerHTML=`<span>${label}</span><strong>${last??'—'} <small>${units[k]}</small></strong><small>${s.time||'尚無測量時間'} · ${pts.length} 筆歷史</small>`;grid.append(card)}content.append(grid);const info=document.createElement('section');info.className='power-card';info.innerHTML=`<h2>同步狀態</h2><p>最後成功：${s.last_success?new Date(s.last_success).toLocaleString():'—'}</p><p>換水標記：${s.water_change?'有':'無'}　備註：${s.note||'—'}</p><button id="water-sync" class="top-button">立即同步</button><details class="mapping-editor"><summary>新增一筆水質資料到 Google Sheet</summary><div class="water-form">${Object.keys(labels).map(k=>`<label>${labels[k]}<input data-water="${k}" type="number" step="any"></label>`).join('')}<label>備註<input data-water="note"></label><label class="check-row"><input data-water="water_change" type="checkbox">本次有換水</label><button id="water-save" class="top-button">寫入並回讀確認</button></div></details>`;info.querySelector('#water-sync').onclick=async e=>{e.target.disabled=true;const r=await fetch('/api/hub/water/sync',{method:'POST'});alert(r.ok?'同步完成':'同步失敗');loadWaterDashboard()};info.querySelector('#water-save').onclick=async e=>{if(!confirm('資料將寫入 Google 試算表並成為新的主資料，確定？'))return;const body={};info.querySelectorAll('[data-water]').forEach(x=>{if(x.type==='checkbox')body[x.dataset.water]=x.checked;else if(x.value!=='')body[x.dataset.water]=x.type==='number'?+x.value:x.value});e.target.disabled=true;const r=await fetch('/api/hub/water/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});alert(r.ok?'Google 寫入並回讀完成':'寫入失敗；請確認 Apps Script 已部署新版');if(r.ok)loadWaterDashboard()};content.append(info);placeholder.classList.add('hidden');content.classList.remove('hidden')}catch(e){placeholder.querySelector('h2').textContent='Google 水質尚未連線';placeholder.querySelector('p').textContent=e.message}}
async function loadDosingDashboard(){const content=document.querySelector('#module-content'),placeholder=document.querySelector('#module-placeholder');try{const d=await json('/api/hub/dosing');content.textContent='';const banner=document.createElement('div');banner.className='mapping-note stale-warning';banner.textContent='模擬模式 · 尚未進行魔點四頭滴定機 BLE 實機驗證；手動操作只更新模擬液量，不會啟動實機。';content.append(banner);const grid=document.createElement('div');grid.className='dosing-grid';for(const h of d.state.heads){const card=document.createElement('section');card.className='power-card dosing-card';card.innerHTML=`<h2>💧 ${h.name}</h2><label>名稱<input data-k="name" value="${h.name}"></label><label>液體<input data-k="liquid" value="${h.liquid||''}" placeholder="KH / Ca / Mg..."></label><label>校正流速 (mL/min)<input data-k="calibration_ml_per_min" type="number" min="0.1" step="0.1" value="${h.calibration_ml_per_min}"></label><label>容器容量 (mL)<input data-k="container_ml" type="number" min="1" value="${h.container_ml}"></label><label>剩餘液量 (mL)<input data-k="remaining_ml" type="number" min="0" value="${h.remaining_ml}"></label><label>每日總量 (mL)<input data-k="daily_ml" type="number" min="0" step="0.1" value="${h.schedule.daily_ml}"></label><label>每日次數<input data-k="doses" type="number" min="1" max="24" value="${h.schedule.doses}"></label><label>開始時間<input data-k="start" type="time" value="${h.schedule.start}"></label><label class="check-row"><input data-k="enabled" type="checkbox" ${h.enabled?'checked':''}>啟用泵頭</label><label class="check-row"><input data-k="schedule_enabled" type="checkbox" ${h.schedule.enabled?'checked':''}>啟用排程</label><div class="dosing-actions"><button data-action="save">儲存並讀回確認</button><button data-action="manual">模擬手動滴定</button><button data-action="calibrate">校正</button></div><small>預估可用 ${h.schedule.daily_ml>0?Math.floor(h.remaining_ml/h.schedule.daily_ml)+' 天':'—'}</small>`;card.querySelector('[data-action=save]').onclick=async()=>{const q=k=>card.querySelector(`[data-k=${k}]`);const body={...h,name:q('name').value,liquid:q('liquid').value,calibration_ml_per_min:+q('calibration_ml_per_min').value,container_ml:+q('container_ml').value,remaining_ml:+q('remaining_ml').value,enabled:q('enabled').checked,schedule:{...h.schedule,daily_ml:+q('daily_ml').value,doses:+q('doses').value,start:q('start').value,enabled:q('schedule_enabled').checked}};const r=await fetch(`/api/hub/dosing/heads/${h.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const x=await r.json();alert(r.ok?'已儲存並讀回確認':'儲存失敗：'+x.error);if(r.ok)loadDosingDashboard()};card.querySelector('[data-action=manual]').onclick=async()=>{const amount=Number(prompt('模擬滴定量 (mL)','1'));if(!amount)return;if(!confirm(`只在模擬器執行 ${amount} mL，不會啟動實機。繼續？`))return;const r=await fetch('/api/hub/dosing/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({head_id:h.id,amount_ml:amount,confirm:true})});const x=await r.json();alert(r.ok?'模擬完成':'失敗：'+x.error);if(r.ok)loadDosingDashboard()};card.querySelector('[data-action=calibrate]').onclick=async()=>{const measured=Number(prompt('量杯實測 mL','10')),seconds=Number(prompt('運轉秒數','10'));if(!measured||!seconds)return;const r=await fetch('/api/hub/dosing/calibrate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({head_id:h.id,measured_ml:measured,seconds})});const x=await r.json();alert(r.ok?`新流速 ${x.calibration_ml_per_min.toFixed(2)} mL/min`:'失敗：'+x.error);if(r.ok)loadDosingDashboard()};grid.append(card)}content.append(grid);const audit=document.createElement('section');audit.className='power-card';audit.innerHTML='<h2>操作紀錄</h2>'+[...d.state.audit].reverse().slice(0,20).map(a=>`<p>${new Date(a.time).toLocaleString()} · 泵頭 ${a.head_id} · ${a.action} · ${a.status}${a.amount_ml?' · '+a.amount_ml+' mL':''}</p>`).join('');content.append(audit);placeholder.classList.add('hidden');content.classList.remove('hidden')}catch(e){placeholder.querySelector('p').textContent=`滴定模擬器載入失敗：${e.message}`}}
async function loadHomeDashboard(){
  const set=(id,text)=>{const el=document.querySelector(id);if(el)el.textContent=text};
  const status=(id,text,kind='')=>{const el=document.querySelector(id);if(el){el.textContent=text;el.dataset.state=kind}};
  try{
    const power=await json('/api/hub/ha/power');
    const watts=power.strips.reduce((n,s)=>n+(Number.parseFloat(s.power&&s.power.state)||0),0);
    const month=power.strips.reduce((n,s)=>n+(Number.parseFloat(s.month&&s.month.state)||0),0);
    const unavailable=power.strips.flatMap(s=>s.outlets).filter(o=>!o.switch||['unavailable','unknown'].includes(o.switch.state)).length;
    set('#home-power',`${watts.toFixed(1)} W`);set('#home-month',`${month.toFixed(2)} kWh`);
    set('#home-devices',power.stale?'HA 已離線':unavailable?`${unavailable} 項離線`:'全部正常');
    status('#module-power',power.stale?'快取資料':'即時連線',power.stale?'stale':'ok');
    const life=document.querySelector('#life-support');if(life){life.textContent='';const names=new Set(['主馬','冷水機馬達','JNS蛋白機','冷水機','珊瑚熊補水器','珊瑚熊捲棉機','滴定機']);for(const o of power.strips.flatMap(s=>s.outlets).filter(o=>names.has(o.name))){const card=document.createElement('article');card.className='metric';const state=o.switch&&o.switch.state;card.innerHTML=`<span>${o.name}</span><strong>${state==='on'?'運轉中':state==='off'?'已關閉':'無資料'}</strong><small>${power.stale?'HA 快取已過期':`插座 ${String(o.slot).padStart(2,'0')} · ${value(o.power,' W')}`}</small>`;life.append(card)}}
  }catch(e){set('#home-devices','HA 未連線');status('#module-power','等待 HA','stale')}
  try{
    const t=await json('/api/hub/temperature');
    if(t.configured&&Number.isFinite(Number(t.value))){set('#home-temperature',Number(t.value).toFixed(1));set('#home-temperature-note',t.stale?'最後成功值 · 資料已過期':`獨立雲端來源 · ${new Date(t.received_time).toLocaleTimeString()}`)}
    else set('#home-temperature-note','尚未設定獨立水溫來源');
    status('#module-temperature',!t.configured?'未設定':t.stale?'已過期':'正常',!t.configured||t.stale?'stale':'ok');
  }catch(e){set('#home-temperature-note','水溫來源異常')}
  try{const w=await json('/api/hub/water');const s=w.status;if(s.configured){set('#home-water',s.time||'已有資料');status('#module-water',s.stale?'快取資料':'同步正常',s.stale?'stale':'ok')}}catch(e){}
  try{const d=await json('/api/hub/dosing');status('#module-dosing',d.state.mode==='simulation'?'模擬模式':'已連線','stale')}catch(e){}
}
async function initUpdates(){
  const button=document.querySelector('#update-check'),auto=document.querySelector('#update-auto'),status=document.querySelector('#update-status'),version=document.querySelector('#version');
  const refresh=async()=>{button.disabled=true;status.textContent='檢查中…';try{const d=await json('/api/update/status');auto.checked=!!d.auto_update;if(d.available){status.textContent=`可更新 ${d.available}`;button.textContent='立即更新';button.dataset.tag=d.available}else{status.textContent='已是最新';button.textContent='檢查更新';delete button.dataset.tag}}catch(e){status.textContent='檢查失敗'}finally{button.disabled=false}};
  const dialog=document.querySelector('#update-dialog'),close=document.querySelector('#update-close'),retry=document.querySelector('#update-retry'),done=document.querySelector('#update-done'),message=document.querySelector('#update-message'),bar=document.querySelector('#update-progress-bar'),targetEl=document.querySelector('#update-target'),elapsed=document.querySelector('#update-elapsed'),steps=[...document.querySelectorAll('#update-steps li')];let timer;
  const stage=(name,text,percent,kind='')=>{const order=['prepare','download','install','restart','health'],at=order.indexOf(name);steps.forEach((x,i)=>{x.className=i<at?'done':i===at?(kind==='error'?'failed':'active'):''});bar.style.width=`${percent}%`;message.textContent=text;message.className=`update-message ${kind}`;status.textContent=text};
  const open=tag=>{dialog.classList.remove('hidden');targetEl.textContent=tag;close.disabled=true;retry.classList.add('hidden');done.classList.add('hidden');const started=Date.now();clearInterval(timer);timer=setInterval(()=>{const s=Math.floor((Date.now()-started)/1000);elapsed.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`},1000)};
  const finish=(ok,text)=>{clearInterval(timer);close.disabled=false;button.disabled=false;if(ok){steps.forEach(x=>x.className='done');bar.style.width='100%';message.className='update-message success';message.textContent=text;status.textContent='更新完成';done.classList.remove('hidden');sessionStorage.removeItem('hubUpdateTarget')}else{const active=steps.find(x=>x.classList.contains('active'));if(active)active.className='failed';message.className='update-message error';message.textContent=text;status.textContent='更新失敗';retry.classList.remove('hidden')}};
  const monitor=async tag=>{const deadline=Date.now()+35*60*1000;let failures=0;stage('download','正在下載更新；網路較慢時可能需要數分鐘…',12);while(Date.now()<deadline){await new Promise(r=>setTimeout(r,1800));try{const p=await json(`/api/update/progress?t=${Date.now()}`);if(p.stage==='failed'){finish(false,`更新失敗：${p.error||'未知錯誤'}`);return}if(p.running){if(p.stage==='download'){const mb=n=>(Number(n||0)/1048576).toFixed(1),known=p.total_bytes>0,detail=known?`${mb(p.downloaded_bytes)} / ${mb(p.total_bytes)} MB · ${Number(p.percent||0).toFixed(1)}%`:`已下載 ${mb(p.downloaded_bytes)} MB`;stage('download',`下載 ${p.file||'更新檔'}：${detail}`,10+Math.min(55,Number(p.percent||0)*.55))}else if(p.stage==='verify')stage('download','下載完成，正在校驗 SHA-256…',68);else if(p.stage==='backup')stage('install','校驗成功，正在備份本機資料…',73);else if(p.stage==='install')stage('install','正在安裝新版並保留舊版回滾點…',78);else if(p.stage==='restart')stage('restart','安裝完成，正在重新啟動 Hub…',86)}}catch(e){}try{const v=await json(`/api/version?t=${Date.now()}`);failures=0;if(v.version===tag){stage('health','新版本已啟動，正在執行健康檢查…',94);const h=await fetch(`/healthz?t=${Date.now()}`,{cache:'no-store'});if(h.ok){finish(true,`${tag} 更新成功，Hub 已恢復正常。`);return}}}catch(e){failures++;if(failures>1)stage('restart','服務重新啟動中，暫時無法連線…',88)}}finish(false,'等待新版本啟動逾時。舊版可能已自動回滾，請按「重新檢查」確認目前版本。')};
  const apply=async tag=>{open(tag);button.disabled=true;sessionStorage.setItem('hubUpdateTarget',tag);stage('prepare','正在向 Hub 確認更新版本…',8);try{const r=await fetch('/api/update/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:true,tag})});const d=await r.json();if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);if(!d.applying){finish(true,'目前已是最新版本，不需要更新。');return}const actual=d.applying;targetEl.textContent=actual;sessionStorage.setItem('hubUpdateTarget',actual);stage('download','伺服器正在下載、校驗並建立安全備份…',38);setTimeout(()=>stage('install','正在安裝新版；原版本保留供自動回滾…',64),1200);await monitor(actual)}catch(e){finish(false,`更新要求失敗：${e.message}`)}};
  button.onclick=async()=>{if(!button.dataset.tag){await refresh();return}const tag=button.dataset.tag;if(confirm(`確定更新到 ${tag}？Hub 服務會短暫重新啟動。`))apply(tag)};
  close.onclick=()=>dialog.classList.add('hidden');done.onclick=()=>location.reload();retry.onclick=async()=>{dialog.classList.add('hidden');sessionStorage.removeItem('hubUpdateTarget');await refresh()};
  auto.onchange=async()=>{try{await fetch('/api/update/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({auto_update:auto.checked})})}catch(e){auto.checked=!auto.checked}};
  version.onclick=async()=>{const box=document.querySelector('#history-dialog'),list=document.querySelector('#history-list');box.classList.remove('hidden');list.innerHTML='<p class="muted">正在讀取 GitHub Release…</p>';try{const d=await json('/api/update/history');const releases=d.releases||[];list.textContent='';if(!releases.length)list.innerHTML='<p class="muted">目前沒有版本紀錄。</p>';for(const r of releases){const item=document.createElement('article');item.className='history-entry';const current=r.tag===d.current;item.innerHTML=`<header><h3>${r.tag}</h3>${current?'<span class="history-current">目前版本</span>':''}<time>${r.published_at?new Date(r.published_at).toLocaleString():'—'}</time></header><p>${r.notes||r.name||'此版本未填寫更新說明'}</p><a href="${r.url}" target="_blank" rel="noopener">在 GitHub 查看完整內容 →</a>`;list.append(item)}}catch(e){list.innerHTML=`<p class="update-message error">版本紀錄讀取失敗：${e.message}</p>`}};
  document.querySelector('#history-close').onclick=()=>document.querySelector('#history-dialog').classList.add('hidden');
  await refresh();
  const pending=sessionStorage.getItem('hubUpdateTarget');if(pending){open(pending);monitor(pending)}
}
function value(state,suffix=''){const n=Number.parseFloat(state&&state.state);return Number.isFinite(n)?`${n.toFixed(n>=100?1:n>=10?2:3)}${suffix}`:'—'}
function toggle(entity,state,onChanged){const label=document.createElement('label');label.className='switch-toggle';const input=document.createElement('input');input.type='checkbox';input.checked=state&&state.state==='on';input.onchange=()=>onChanged(entity,input.checked,input);const span=document.createElement('span');label.append(input,span);return label}
async function setHASwitch(entity,on,input,critical=false){if(critical&&!on&&!confirm('這是重要生命維持設備，確定要關閉嗎？')){input.checked=true;return}input.disabled=true;try{const r=await fetch('/api/hub/ha/switch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entity_id:entity,on,confirm:critical&&!on})});if(!r.ok)throw new Error(r.status);setTimeout(loadPowerDashboard,500)}catch(e){input.checked=!on;alert('HA 開關操作失敗')}finally{input.disabled=false}}
async function loadPowerDashboard(){
  const content=document.querySelector('#module-content'),placeholder=document.querySelector('#module-placeholder');
  try{
    const data=await json('/api/hub/ha/power');
    content.textContent='';
    if(data.stale){const warning=document.createElement('div');warning.className='mapping-note stale-warning';warning.textContent='Home Assistant 連線中斷；以下為最後快取資料，為避免誤操作已暫停開關控制。';content.append(warning)}
    const detail=document.createElement('div');detail.className='power-detail-grid';
    const summary=document.createElement('div');summary.className='power-summary-grid';
    for(const strip of data.strips){
      const card=document.createElement('section');card.className='power-card';card.innerHTML=`<h2>⚡ ${strip.name}詳情</h2>`;
      const led=document.createElement('div');led.className='power-row led-row';led.innerHTML='<strong>☀ 設備 LED 指示燈</strong>';led.append(toggle(strip.led_entity,strip.led,setHASwitch));card.append(led);
      for(const outlet of strip.outlets){const row=document.createElement('div');row.className='power-row outlet-row';const name=document.createElement('strong');name.textContent=`${String(outlet.slot).padStart(2,'0')}-${outlet.name}`;const metrics=document.createElement('div');metrics.className='outlet-metrics';metrics.innerHTML=`<span><small>V</small>${value(outlet.voltage)}</span><span><small>A</small>${value(outlet.current)}</span><span><small>W</small>${value(outlet.power)}</span><span><small>今日</small>${value(outlet.today,' kWh')}</span><span><small>本月</small>${value(outlet.month,' kWh')}</span>`;row.append(name,metrics,toggle(outlet.switch_entity,outlet.switch,(entity,on,input)=>setHASwitch(entity,on,input,outlet.critical)));card.append(row)}
      detail.append(card);
      const totals=document.createElement('section');totals.className='power-card totals-card';totals.innerHTML=`<h2>📊 ${strip.name.split(' ')[0]} 總能耗統計</h2><dl><div><dt>〰 當前總安培數 (A)</dt><dd>${value(strip.current,' A')}</dd></div><div><dt>ϟ 當前總瓦數 (W)</dt><dd>${value(strip.power,' W')}</dd></div><div><dt>ϟ 今日總累積 (kWh)</dt><dd>${value(strip.today,' kWh')}</dd></div><div><dt>ϟ 本月總累積 (kWh)</dt><dd>${value(strip.month,' kWh')}</dd></div><div><dt>◷ 連續運行時間</dt><dd>${strip.on_since&&strip.on_since.state||'—'}</dd></div></dl>`;summary.append(totals)
    }
    const charts=document.createElement('div');charts.className='power-chart-grid';charts.innerHTML='<section class="power-card chart-card"><h2>7 天瓦數變化 (W)</h2><canvas id="power-chart"></canvas></section><section class="power-card chart-card"><h2>7 天電流變化 (A)</h2><canvas id="current-chart"></canvas></section><section class="power-card chart-card"><h2>30 天累積用電 (kWh)</h2><canvas id="energy-chart"></canvas></section>';
    if(data.stale)detail.querySelectorAll('input').forEach(input=>input.disabled=true);content.append(detail,summary,charts);placeholder.classList.add('hidden');content.classList.remove('hidden');loadPowerHistory(data);loadMappingEditor(content);
  }catch(e){placeholder.classList.remove('hidden');placeholder.querySelector('h2').textContent='Home Assistant 尚未連線';placeholder.querySelector('p').textContent=`無法讀取即時電力資料：${e.message}`}
}
async function loadMappingEditor(content){try{const data=await json('/api/hub/equipment');const details=document.createElement('details');details.className='mapping-editor';details.innerHTML='<summary>設備插座對應設定</summary><p>設備換插座時在此重新指定；若實體已占用，兩個邏輯設備會自動交換。</p>';const grid=document.createElement('div');grid.className='mapping-editor-grid';for(const device of data.devices){const row=document.createElement('label');row.innerHTML=`<strong>${String(device.slot).padStart(2,'0')} · ${device.display_name}</strong>`;const select=document.createElement('select');for(const optionDevice of data.devices){const option=document.createElement('option');option.value=optionDevice.switch_entity;option.textContent=`${String(optionDevice.slot).padStart(2,'0')} · ${optionDevice.switch_entity}`;option.selected=optionDevice.switch_entity===device.switch_entity;select.append(option)}select.onchange=async()=>{if(!confirm(`將「${device.display_name}」重新指定到所選 HA 實體？`)){select.value=device.switch_entity;return}const r=await fetch(`/api/hub/equipment/${encodeURIComponent(device.id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({switch_entity:select.value})});if(!r.ok){alert('儲存失敗');select.value=device.switch_entity}else location.reload()};row.append(select);grid.append(row)}details.append(grid);content.append(details)}catch(e){}}
async function loadPowerHistory(power){try{const ids=[...power.strips.map(s=>s.power.entity_id),...power.strips.map(s=>s.current.entity_id),power.temperature.entity_id].filter(Boolean);const history=await json(`/api/hub/storage/history?hours=168&entity_ids=${encodeURIComponent(ids.join(','))}`);const colors=['#ff9700','#1ec8ff','#ff2d68'];drawHistory(document.querySelector('#power-chart'),history,power.strips.map(s=>s.power.entity_id),colors);drawHistory(document.querySelector('#current-chart'),history,power.strips.map(s=>s.current.entity_id),['#18e817','#ef19eb','#ffd400']);drawHistory(document.querySelector('#temperature-chart'),history,[power.temperature.entity_id],['#15d2d2'])}catch(e){}}
function drawHistory(canvas,groups,ids,colors){if(!canvas)return;const ratio=devicePixelRatio||1,w=canvas.clientWidth||500,h=210;canvas.width=w*ratio;canvas.height=h*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#263940';ctx.beginPath();for(let i=1;i<5;i++){ctx.moveTo(0,i*h/5);ctx.lineTo(w,i*h/5)}ctx.stroke();const series=(groups||[]).map(g=>({id:g[0]&&g[0].entity_id,points:g.map(x=>({t:Date.parse(x.last_updated||x.last_changed),v:Number.parseFloat(x.state)})).filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.v))}));const selected=ids.map(id=>series.find(s=>s.id===id)).filter(Boolean);const pts=selected.flatMap(s=>s.points);if(!pts.length)return;const minT=Math.min(...pts.map(p=>p.t)),maxT=Math.max(...pts.map(p=>p.t)),minV=Math.min(...pts.map(p=>p.v)),maxV=Math.max(...pts.map(p=>p.v));selected.forEach((s,i)=>{ctx.strokeStyle=colors[i%colors.length];ctx.lineWidth=3;ctx.beginPath();s.points.forEach((p,j)=>{const x=(p.t-minT)/Math.max(1,maxT-minT)*w,y=h-8-(p.v-minV)/Math.max(.001,maxV-minV)*(h-16);j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
async function loadSystemDashboard(){const content=document.querySelector('#module-content'),placeholder=document.querySelector('#module-placeholder');try{const [hub,storage,update,temp]=await Promise.all([json('/api/hub/status'),json('/api/hub/storage/status'),json('/api/update/status'),json('/api/hub/temperature')]);content.innerHTML=`<div class="system-grid"><section class="power-card"><h2>Hub</h2><dl><div><dt>版本</dt><dd>${hub.version}</dd></div><div><dt>平台</dt><dd>Raspberry Pi arm64</dd></div></dl></section><section class="power-card"><h2>本機資料庫</h2><dl><div><dt>資料庫</dt><dd>${storage.database}</dd></div><div><dt>HA 樣本</dt><dd>${storage.samples}</dd></div><div><dt>獨立水溫樣本</dt><dd>${storage.temperature_samples}</dd></div><div><dt>保留政策</dt><dd>永久</dd></div></dl></section><section class="power-card"><h2>資料來源</h2><dl><div><dt>小魚未來</dt><dd>${!temp.configured?'未設定':temp.stale?'資料過期':'正常'}</dd></div><div><dt>Google 水質</dt><dd>Phase 4 尚未建置</dd></div></dl></section><section class="power-card"><h2>OTA</h2><dl><div><dt>目前</dt><dd>${update.current}</dd></div><div><dt>狀態</dt><dd>${update.available?'可更新 '+update.available:'最新'}</dd></div></dl></section></div><div class="system-actions"><button id="db-backup" class="top-button">立即備份資料庫</button><a class="top-button" href="/api/hub/storage/export">匯出 SQLite</a></div>`;content.querySelector('#db-backup').onclick=async e=>{e.target.disabled=true;const r=await fetch('/api/hub/storage/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:true})});const d=await r.json();alert(r.ok?`備份完成：${d.backup}`:`備份失敗：${d.error}`);e.target.disabled=false};placeholder.classList.add('hidden');content.classList.remove('hidden')}catch(e){placeholder.querySelector('p').textContent=`系統資料載入失敗：${e.message}`}}
const legacyDosingDashboard=loadDosingDashboard;
loadDosingDashboard=async function(){
  await legacyDosingDashboard();
  const content=document.querySelector('#module-content'); if(!content||content.classList.contains('hidden'))return;
  const d=await json('/api/hub/dosing'),c=d.state.calculator;
  const section=document.createElement('section');section.className='power-card calculator-card';
  section.innerHTML=`<h2>滴定計算工具</h2><p class="muted">純計算，不會啟動、設定或傳送資料到滴定機。</p><div class="calc-settings">
  ${[['tank_liters','缸體積 (L)'],['po4_concentration','PO₄ 溶液濃度'],['no3_concentration','NO₃ 溶液濃度'],['kh_efficiency','KH 溶液效能'],['po4_daily_limit','PO₄ 每日上限'],['no3_daily_limit','NO₃ 每日上限'],['kh_daily_limit','KH 每日上限']].map(([k,l])=>`<label>${l}<input data-calc-setting="${k}" type="number" step="any" value="${c[k]}"></label>`).join('')}</div>
  <div class="calc-grid">${[['po4','PO₄','ppm'],['no3','NO₃','ppm'],['kh','KH','dKH']].map(([k,l,u])=>`<article><h3>${l}</h3><label>目標增加量 (${u})<input data-target="${k}" type="number" step="any"></label><output data-dose="${k}">— mL</output><label>輸入滴定量 (mL)<input data-amount="${k}" type="number" step="any"></label><output data-rise="${k}">— ${u}</output><small data-limit="${k}"></small></article>`).join('')}</div><button id="calc-save" class="top-button">儲存計算參數</button>`;
  section.querySelector('#calc-save').textContent='儲存配方與缸體參數';section.querySelector('#calc-save').insertAdjacentHTML('afterend','<small class="muted">僅保存計算基準，不會操作滴定機。</small>');
  const coefficient=k=>k==='po4'?+section.querySelector('[data-calc-setting=po4_concentration]').value/+section.querySelector('[data-calc-setting=tank_liters]').value:k==='no3'?+section.querySelector('[data-calc-setting=no3_concentration]').value/+section.querySelector('[data-calc-setting=tank_liters]').value:+section.querySelector('[data-calc-setting=kh_efficiency]').value/+section.querySelector('[data-calc-setting=tank_liters]').value;
  const calculate=()=>{for(const k of ['po4','no3','kh']){const f=coefficient(k),target=+section.querySelector(`[data-target=${k}]`).value,amount=+section.querySelector(`[data-amount=${k}]`).value,rise=amount*f,limit=+section.querySelector(`[data-calc-setting=${k}_daily_limit]`).value;section.querySelector(`[data-dose=${k}]`).textContent=target?`${(target/f).toFixed(3)} mL`:'— mL';section.querySelector(`[data-rise=${k}]`).textContent=amount?rise.toFixed(4):'—';const msg=section.querySelector(`[data-limit=${k}]`);msg.textContent=amount?(rise>limit?`超過每日上限 ${limit}`:`每日上限內 (${limit})`):'';msg.className=rise>limit?'calc-alert':'calc-ok'}};
  section.querySelectorAll('input').forEach(x=>x.oninput=calculate);section.querySelector('#calc-save').onclick=async()=>{const body={};section.querySelectorAll('[data-calc-setting]').forEach(x=>body[x.dataset.calcSetting]=+x.value);const r=await fetch('/api/hub/dosing/calculator',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});alert(r.ok?'計算參數已儲存':'儲存失敗')};content.append(section);
};

