  try{const [d,t]=await Promise.all([json('/api/hub/water'),json('/api/hub/temperature')]),labels={temperature:'水溫',ca:'Ca',mg:'Mg',kh:'KH',no3:'NO₃',po4:'PO₄',sg:'鹽度'},units={temperature:'°C',ca:'ppm',mg:'ppm',kh:'dKH',no3:'ppm',po4:'ppm',sg:'SG'},grid=document.querySelector('#water-dashboard');grid.textContent='';for(const[k,l]of Object.entries(labels)){const p=k==='temperature'?(t.configured?{value:t.value,time:t.source_time}:null):d.latest[k],c=document.createElement('article');c.className='parameter-card';c.innerHTML=`<span>${l}</span><strong>${p?Number(p.value).toFixed(k==='sg'?3:1):'—'} <small>${units[k]}</small></strong><time>${p?new Date(p.time).toLocaleString():'尚無紀錄'}</time>`;grid.append(c)}const records=d.records||[],recencies=[['NP 量測',records.find(r=>r.no3!=null&&r.po4!=null)?.measured_at],['三大元素量測',records.find(r=>r.ca!=null&&r.mg!=null&&r.kh!=null)?.measured_at],['最近一次換水',records.find(r=>r.water_change)?.measured_at]];for(const[label,time]of recencies){const days=time?daysSince(time):null,c=document.createElement('article');c.className='parameter-card recency-card';const cls=days==null?'missing':days<=7?'fresh':days<=14?'warning':'overdue';c.innerHTML=`<span>${label}</span><strong class="${cls}">${days==null?'尚無紀錄':days+' 天'}</strong><time>${time?new Date(time).toLocaleString():'需要新增紀錄'}</time>`;grid.append(c)}set('#home-water',`${d.count} 筆`)}catch(e){}
